"""Command-line parsing and user-facing diagnostics.

The parser is deliberately independent of argparse, since the interface uses
optional values, command argument groups, and last-occurrence overrides.
"""
import os
import re
import sys
import difflib
import pwd
import grp
from dataclasses import dataclass, field


class EarlyExit(Exception):
    def __init__(self, code=0, text='', stderr=False):
        self.code, self.text, self.stderr = code, text, stderr


MORE = "For more information, try '--help'.\n"


def fd_error(text):
    raise EarlyExit(1, '[fd error]: ' + text + '\n', True)


@dataclass
class Spec:
    name: str
    kind: str = 'flag'
    value: str = ''
    choices: tuple = ()
    repeat: bool = False
    empty: bool = True
    aliases: tuple = ()
    short: str = ''

    @property
    def display(self):
        if self.kind == 'optional':
            return '--' + self.name + '[=<' + self.value + '>]'
        if self.kind == 'command':
            return '--' + self.name + ' <cmd>...'
        if self.value:
            return '--' + self.name + ' <' + self.value + '>'
        if self.name == 'one-result':
            return '-1'
        return '--' + self.name


SPECS = [
    Spec('hidden', short='H'), Spec('no-hidden'),
    Spec('no-ignore', short='I'), Spec('ignore'),
    Spec('no-ignore-vcs'), Spec('ignore-vcs'),
    Spec('no-require-git'), Spec('require-git'), Spec('no-ignore-parent'),
    Spec('unrestricted', short='u'),
    Spec('case-sensitive', short='s'), Spec('ignore-case', short='i'),
    Spec('glob', short='g'), Spec('regex'), Spec('fixed-strings', short='F'),
    Spec('and', 'str', 'pattern', repeat=True),
    Spec('absolute-path', short='a'), Spec('relative-path'),
    Spec('list-details', short='l'),
    Spec('follow', short='L'), Spec('no-follow'), Spec('full-path', short='p'),
    Spec('print0', short='0'),
    Spec('max-depth', 'number', 'depth', short='d'),
    Spec('min-depth', 'number', 'depth'), Spec('exact-depth', 'number', 'depth'),
    Spec('exclude', 'str', 'pattern', repeat=True, short='E'), Spec('prune'),
    Spec('type', 'choice', 'filetype', ('file','directory','symlink','block-device','char-device','executable','empty','socket','pipe'), True, False, short='t'),
    Spec('extension', 'str', 'ext', repeat=True, short='e'),
    Spec('size', 'size', 'size', repeat=True, short='S'),
    Spec('changed-within', 'str', 'date|dur', aliases=('change-newer-than','newer','changed-after')),
    Spec('changed-before', 'str', 'date|dur', aliases=('change-older-than','older')),
    Spec('owner', 'owner', 'user:group', short='o'),
    Spec('format', 'str', 'fmt'),
    Spec('exec', 'command', 'cmd', repeat=True, short='x'),
    Spec('exec-batch', 'command', 'cmd', repeat=True, short='X'),
    Spec('batch-size', 'number', 'size'),
    Spec('ignore-file', 'str', 'path', repeat=True, empty=False),
    Spec('color', 'choice', 'when', ('auto','always','never'), empty=False, short='c'),
    Spec('hyperlink', 'optional', 'when', ('auto','always','never'), empty=False),
    Spec('ignore-contain', 'str', 'name', repeat=True, empty=False),
    Spec('threads', 'number', 'num', short='j'),
    Spec('max-results', 'number', 'count'), Spec('one-result', short='1'),
    Spec('quiet', aliases=('has-results',), short='q'), Spec('show-errors'),
    Spec('base-directory', 'str', 'path', empty=False, short='C'),
    Spec('path-separator', 'str', 'separator'),
    Spec('search-path', 'str', 'search-path', repeat=True, empty=False),
    Spec('strip-cwd-prefix', 'optional', 'when', ('auto','always','never'), empty=False),
    Spec('one-file-system', aliases=('mount','xdev')),
    Spec('help', short='h'), Spec('version', short='V'),
]
BY_NAME = {s.name: s for s in SPECS}
LONG = {n: s for s in SPECS for n in (s.name,) + s.aliases if n != 'one-result'}
SHORT = {s.short: s for s in SPECS if s.short}
TYPE_ALIASES = {'f':'file','d':'directory','dir':'directory','l':'symlink','b':'block-device','c':'char-device','s':'socket','p':'pipe','x':'executable','e':'empty'}


@dataclass
class Options:
    values: dict = field(default_factory=dict)
    order: list = field(default_factory=list)
    positional: list = field(default_factory=list)
    program: str = 'executable'

    def get(self, name, default=None):
        return self.values.get(name, default)

    def has(self, name):
        return name in self.values

    def flag(self, name):
        return bool(self.values.get(name, False))

    def many(self, name):
        return self.values.get(name, [])

    def usage(self, omit=(), add=(), generic=False, missing=()):
        if generic:
            return 'Usage: ' + self.program + ' [OPTIONS] [pattern] [path]...'
        names = [k for k in self.order if k in self.values and k not in omit]
        for k in add:
            if k not in names:
                names.append(k)
        # A required command precedes the option which requires it.
        for k in reversed(missing):
            if k not in names:
                names.insert(0, k)
        parts = []
        for k in names:
            if k in ('pattern','path'):
                continue
            parts.append(BY_NAME[k].display)
        parts.append('<pattern>' if self.positional else '[pattern]')
        parts.append('<path>...' if len(self.positional)>1 and 'path' not in omit else '[path]...')
        return 'Usage: ' + self.program + ' ' + ' '.join(parts)

    def record(self, name, value):
        pairs = [('hidden','no-hidden'),('no-ignore','ignore'),('no-ignore-vcs','ignore-vcs'),
                 ('no-require-git','require-git'),('case-sensitive','ignore-case'),
                 ('glob','regex'),('absolute-path','relative-path'),('follow','no-follow'),
                 ('one-result','max-results')]
        for a,b in pairs:
            if name == a:
                self.values.pop(b, None)
            elif name == b:
                self.values.pop(a, None)
        if name == 'unrestricted':
            self.values.pop('no-hidden',None)
            self.values.pop('ignore',None)
            self.values['hidden'] = True
            self.values['no-ignore'] = True
        spec = BY_NAME[name]
        if spec.repeat:
            self.values.setdefault(name, []).append(value)
        else:
            self.values[name] = value
        if name not in self.order:
            self.order.append(name)

    def simple_error(self, msg, usage=None):
        text = 'error: ' + msg + '\n\n'
        if usage:
            text += usage + '\n\n'
        raise EarlyExit(2, text + MORE, True)

    def missing(self, spec):
        msg = "error: a value is required for '" + spec.display + "' but none was supplied\n"
        if spec.choices:
            msg += '  [possible values: ' + ', '.join(spec.choices) + ']\n'
        raise EarlyExit(2, msg + '\n' + MORE, True)

    def invalid(self, spec, value, why=None):
        msg = "error: invalid value '" + value + "' for '" + spec.display + "'"
        if why:
            msg += ': ' + why
        msg += '\n'
        if spec.choices:
            msg += '  [possible values: ' + ', '.join(spec.choices) + ']\n'
            similar = suggestion(value, spec.choices)
            if similar:
                msg += "\n  tip: a similar value exists: '" + similar + "'\n"
        raise EarlyExit(2, msg + '\n' + MORE, True)

    def unknown(self, token):
        similar = None
        if token.startswith('--'):
            similar = suggestion(token[2:].split('=')[0], LONG.keys())
        msg = "error: unexpected argument '" + token + "' found\n\n"
        if similar:
            spec = LONG[similar]
            msg += "  tip: a similar argument exists: '--" + similar + "'\n\n"
            usage = self.usage(add=[spec.name])
        else:
            msg += "  tip: to pass '" + token + "' as a value, use '-- " + token + "'\n\n"
            usage = self.usage(generic=True)
        raise EarlyExit(2, msg + usage + '\n\n' + MORE, True)


def jaro(a,b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    width = max(len(a),len(b))//2-1
    width = max(width,0)
    aa,bb = [False]*len(a),[False]*len(b)
    for i,c in enumerate(a):
        for j in range(max(0,i-width),min(len(b),i+width+1)):
            if not bb[j] and c == b[j]:
                aa[i]=bb[j]=True
                break
    count=sum(aa)
    if not count:
        return 0.0
    left=[c for i,c in enumerate(a) if aa[i]]
    right=[c for i,c in enumerate(b) if bb[i]]
    trans=sum(x!=y for x,y in zip(left,right))/2
    score=(count/len(a)+count/len(b)+(count-trans)/count)/3
    prefix=0
    for x,y in zip(a,b):
        if x!=y or prefix==4:break
        prefix+=1
    return score + prefix*.1*(1-score) if score > .7 else score


def suggestion(text, choices):
    matches=[(jaro(text,c),c) for c in choices]
    if not matches:return None
    score,name=max(matches, key=lambda x:x[0])
    return name if score > .8 else None


def parse_size(raw):
    m=re.fullmatch(r'([+-]?)([0-9]+)([a-zA-Z]+)',raw)
    if not m:
        raise ValueError("'"+raw+"' is not a valid size constraint. See 'fd --help'.")
    sign,n,unit=m.groups();unit=unit.lower()
    scales={'b':1}
    for power,u in enumerate('kmgt',1):
        scales[u]=scales[u+'b']=1000**power
        scales[u+'i']=scales[u+'ib']=1024**power
    if unit not in scales:
        raise ValueError("'"+raw+"' is not a valid size constraint. See 'fd --help'.")
    size=int(n)*scales[unit]
    if size > 18446744073709551615:
        raise ValueError("'"+raw+"' is not a valid size constraint. See 'fd --help'.")
    return (sign,size)


def parse_owner(raw):
    if raw.count(':')>1:
        raise ValueError("more than one ':' present in owner string '"+raw+"'. See 'fd --help'.")
    parts=raw.split(':')
    result=[]
    for idx,part in enumerate(parts):
        if not part:
            result.append(None);continue
        neg=part.startswith('!')
        name=part[1:] if neg else part
        number=None
        if re.fullmatch(r'\+?[0-9]+',name) and int(name)<=4294967295:
            number=int(name)
        else:
            try:
                number=pwd.getpwnam(name).pw_uid if idx==0 else grp.getgrnam(name).gr_gid
            except (KeyError,ValueError,OverflowError):
                noun='user' if idx==0 else 'group'
                raise ValueError("'"+name+"' is not a recognized "+noun+" name")
        result.append((number,neg))
    return tuple((result+[None,None])[:2])


def validate_value(opts,spec,raw):
    if raw == '' and not spec.empty:
        opts.missing(spec)
    if spec.kind in ('choice','optional'):
        val=TYPE_ALIASES.get(raw,raw) if spec.name=='type' else raw
        if val not in spec.choices:
            opts.invalid(spec,raw)
        return val
    if spec.kind=='number':
        if not raw:
            opts.invalid(spec,raw,'cannot parse integer from empty string')
        if not re.fullmatch(r'\+?[0-9]+',raw):
            opts.invalid(spec,raw,'invalid digit found in string')
        n=int(raw)
        if n>18446744073709551615:
            opts.invalid(spec,raw,'number too large to fit in target type')
        if spec.name=='threads' and n==0:
            opts.invalid(spec,raw,'number would be zero for non-zero type')
        return n
    if spec.kind in ('size','owner'):
        try:
            return parse_size(raw) if spec.kind=='size' else parse_owner(raw)
        except ValueError as e:
            opts.invalid(spec,raw,str(e))
    return raw


def conflicts(opts):
    pairs=[('glob','fixed-strings'),('max-depth','exact-depth'),('min-depth','exact-depth'),
           ('exec','exec-batch'),('list-details','exec'),('list-details','exec-batch'),
           ('list-details','print0'),('list-details','format'),
           ('quiet','exec'),('quiet','exec-batch'),('quiet','list-details'),('quiet','max-results'),
           ('strip-cwd-prefix','path'),('strip-cwd-prefix','search-path'),('path','search-path')]
    present=list(k for k in opts.order if k in opts.values or k=='path')
    if len(opts.positional)>1 and 'path' not in present:present.append('path')
    def display(k):return '[path]...' if k=='path' else BY_NAME[k].display
