"""Filesystem traversal and metadata predicates."""
import os
import stat
import time
import re
import datetime
from dataclasses import dataclass
from cli import fd_error
from ignores import IgnoreEngine, write_error


def duration_or_date(value):
    try:
        if re.fullmatch(r'@[0-9]+',value):
            n=int(value[1:])
            if n > 9223372036854775807:raise ValueError()
            return float(n)
        if re.match(r'^\d{4}-\d{1,2}-\d{1,2}',value):
            text=value
            if text.endswith(('Z','z')):text=text[:-1]+'+00:00'
            try:
                return datetime.datetime.fromisoformat(text).timestamp()
            except (ValueError,OverflowError):
                return datetime.datetime.strptime(value,'%Y-%m-%d').timestamp()
        units={
            'nsec':1e-9,'ns':1e-9,'nanosecond':1e-9,'nanoseconds':1e-9,
            'usec':1e-6,'us':1e-6,'µs':1e-6,'microsecond':1e-6,'microseconds':1e-6,
            'msec':.001,'ms':.001,'millisecond':.001,'milliseconds':.001,
            's':1,'sec':1,'secs':1,'second':1,'seconds':1,
            'm':60,'min':60,'mins':60,'minute':60,'minutes':60,
            'h':3600,'hr':3600,'hrs':3600,'hour':3600,'hours':3600,
            'd':86400,'day':86400,'days':86400,
            'w':604800,'week':604800,'weeks':604800,
            'M':2630016,'month':2630016,'months':2630016,
            'y':31557600,'year':31557600,'years':31557600,
        }
        if value.strip()=='0':return time.time()
        total=0.;pos=0;found=False
        for m in re.finditer(r'([0-9]+(?:\.[0-9]+)?)\s*([a-zA-Zµ]+)',value):
            if value[pos:m.start()].strip():raise ValueError()
            if m[2] not in units:raise ValueError()
            total+=float(m[1])*units[m[2]];pos=m.end();found=True
        if not found or value[pos:].strip():raise ValueError()
        return time.time()-total
    except (ValueError,OverflowError,OSError):
        fd_error("'"+value+"' is not a valid date or duration. See 'fd --help'.")


@dataclass
class Entry:
    path: str
    name: str
    depth: int
    metadata: object
    absolute: str
    link: bool=False

    @property
