def encoded(text):
    return text.encode('utf-8','surrogateescape')


def stem(name):
    dot=name.rfind('.')
    if dot>0:name=name[:dot]
    return '' if name=='.' else name


def parent(path):
    if '/' not in path:return '.'
    value=path.rsplit('/',1)[0]
    while value.endswith('/') or value.endswith('/.'):
        value=value[:-1] if value.endswith('/') else value[:-2]
    if not value:return '/' if path.startswith('/') else '.'
    return value


def extensionless(path):
    # Reassembling components intentionally removes redundant current-directory
    # components while retaining parent-directory components.
    parts=path.split('/')
    parts[-1]=stem(parts[-1])
    result='/'.join(p for p in parts if p not in ('','.'))
    return ('/' if path.startswith('/') else '')+result


class Template:
