"""Execution of user-provided commands with path placeholder substitution."""
import os
import sys
import subprocess
from output import Template
from cli import EarlyExit, MORE
from ignores import write_error


class Command:
    def __init__(self,args,batch=False):
        self.args=[Template(arg) for arg in args]
        count=sum(arg.has_placeholder for arg in self.args)
        if not count:self.args.append(Template('{}'))
        if batch and count>1:
            raise EarlyExit(2,'error: Only one placeholder allowed for batch commands\n\nUsage: fd [OPTIONS] [pattern] [path]...\n\n'+MORE,True)

    def expand(self,paths,separator):
        argv=[]
        for template in self.args:
            if template.has_placeholder:
                argv.extend(template.render(path,separator) for path in paths)
            else:argv.append(template.render('',separator))
        return argv


def execute(argv):
    try:
