def execute_parallel(opts,walker,commands,separator,threads):
    lock=threading.Lock()
    def task(entry):
        path=walker.display_path(entry)
        stdout=[];stderr=[];success=True
        for command in commands:
            argv=command.expand([path],separator)
            try:
                result=subprocess.run(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
                stdout.append(result.stdout);stderr.append(result.stderr)
                if result.returncode:
                    success=False;break
            except (FileNotFoundError,ValueError):
                stderr.append(os.fsencode('[fd error]: Command not found: '+(argv[0] if argv else '')+'\n'))
                success=False;break
            except OSError as err:
                stderr.append(os.fsencode('[fd error]: Problem while executing command: '+err.strerror+' (os error '+str(err.errno)+')\n'))
                success=False;break
        if opts.flag('print0'):stdout.append(b'\0')
        with lock:
            sys.stdout.buffer.write(b''.join(stdout));sys.stdout.buffer.flush()
            sys.stderr.buffer.write(b''.join(stderr));sys.stderr.buffer.flush()
        return success
    success=True
    with ThreadPoolExecutor(max_workers=min(threads,1024)) as pool:
        pending=set()
        for entry in walker:
            pending.add(pool.submit(task,entry))
            if len(pending)>=max(2,threads*2):
                done,pending=wait(pending,return_when=FIRST_COMPLETED)
                for future in done:
                    if not future.result():success=False
        for future in pending:
            if not future.result():success=False
    return 0 if success else 1
